#include <stdio.h>
#include <string.h>

int my_strlen(const char *s) {
    int n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

int main(void) {
    char word[10] = "lab";
    char copy[10];
    strcpy(copy, word);
    copy[0] = 'L';
    printf("%s %s %d %zu\n", word, copy, my_strlen(word), strlen(copy));
    return 0;
}
